public String checkYourself(int guess) {
  String result = "miss";                 // 默认没中（修正了 prep 的隐患）
  for (int cell : locationCells) {        // 增强 for：遍历每个格子
    if (guess == cell) {                  // int 比较用 ==
      result = "hit";
      numOfHits++;                        // 自增：等价于 numOfHits = numOfHits + 1
      break;                              // 找到就跳出，无需继续
    }
  }
  if (numOfHits == locationCells.length) { // 全中 → 击沉
    result = "kill";
  }
  System.out.println(result);             // 打印给用户
  return result;                          // 返回给调用者
}

